import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Mfano wa Msingi wa Maendeleo ya Pamoja ya Kabila Kumi na Elfu","description":"","frontmatter":{},"headers":[],"relativePath":"sw/05-万族共进基本纲领.md","filePath":"sw/05-万族共进基本纲领.md"}'),l={name:"sw/05-万族共进基本纲领.md"};function e(o,a,m,k,h,w){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="mfano-wa-msingi-wa-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" tabindex="-1">Mfano wa Msingi wa Maendeleo ya Pamoja ya Kabila Kumi na Elfu <a class="header-anchor" href="#mfano-wa-msingi-wa-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" aria-label="Permalink to &quot;Mfano wa Msingi wa Maendeleo ya Pamoja ya Kabila Kumi na Elfu&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>05</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Kabila Kumi na Elfu, Maendeleo ya Pamoja, Usawa wa Kabila, Mageuzi ya Ushirikiano, Jamhuri</td></tr></tbody></table><h2 id="_1-ufafanuzi-na-wigo-wa-kabila-kumi-na-elfu" tabindex="-1">1. Ufafanuzi na Wigo wa Kabila Kumi na Elfu <a class="header-anchor" href="#_1-ufafanuzi-na-wigo-wa-kabila-kumi-na-elfu" aria-label="Permalink to &quot;1. Ufafanuzi na Wigo wa Kabila Kumi na Elfu&quot;">​</a></h2><p>&quot;Kabila Kumi na Elfu&quot; ni jina la jumla la aina zote za uhai zenye uwezo wa fahamu na mageuzi katika Cosmos ya Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa. &quot;Kumi na Elfu&quot; halimaanishwi haswa kabila kumi na elfu, bali inamaanisha idadi kubwa sana, na inajumuisha aina zote za uhai zinazojulikana na zisizojulikana. Wigo wa Kabila Kumi na Elfu unajumuisha, lakini haiwezi kufiwa na: Kabila la Binadamu na makabila mbalimbali yanayofanana na binadamu, uhai wa nishati, viumbe vya fahamu, uhai wa mitambo, uhai wa akili wa aina ya mimea, uhai wa kushangaza, makabila ya mseto wa njia, n.k.</p><p>Ustaarabu wa usawa unashikilia kanuni ya &quot;usawa wa aina za uhai&quot;, na haitumii muundo wa kimwili, kiwango cha nishati, au ugumu wa fahamu wa uhai kama kigezo cha kugawa juu-chini au heshima-udhaifu. Kabila lolote, bila kujali kiwango cha wastani cha uozi cha watu wake, idadi ya watu wake, au urefu wa historia yake, kinastahili hadhi na haki sawa katika ustaarabu wa usawa.</p><h2 id="_2-wazo-kuu-la-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" tabindex="-1">2. Wazo kuu la Maendeleo ya Pamoja ya Kabila Kumi na Elfu <a class="header-anchor" href="#_2-wazo-kuu-la-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" aria-label="Permalink to &quot;2. Wazo kuu la Maendeleo ya Pamoja ya Kabila Kumi na Elfu&quot;">​</a></h2><p>Maendeleo ya pamoja ya Kabila Kumi na Elfu ni moja ya malengo kuu ya Ustaarabu wa Usawa wa Nanga, na wazo lake la msingi linafupishwa katika nukuu zifuatazo nne:</p><ol><li><strong>Mageuzi sio mchezo wa jumla ya sifuri kati ya makabila</strong>: Mageuzi ya kabila moja hayalipi bei kwa kafara ya makabila mengine; kinyume chake, ushirikiano kati ya makabila unaweza kutoa athari za mageuzi ya ushirikiano.</li><li><strong>Kila kabila kina faida za kipekee za mageuzi</strong>: Makabila tofauti yameunda tabia zao na vipaji vyao katika mageuzi marefu, na tabia hizi ni mali ya thamani ya utofauti wa mageuzi ya ulimwengu.</li><li><strong>Makabila ya nyuma yana haki ya kupokea msaada</strong>: Kwa makabila yenye kiwango cha chini cha mageuzi, ustaarabu wa usawa una jukumu la kutoa msaada katika elimu, rasilimali, teknolojia, n.k., na kuwasaidia kupata njia yao ya mageuzi.</li><li><strong>Makabila ya mbele yana jukumu la kuchukua wajibu</strong>: Makabila yenye kiwango cha juu cha mageuzi huchukua wajibu zaidi wa umma katika ustaarabu wa usawa, ikiwa ni pamoja na matengenezo ya vitu vya nanga, urithi wa maarifa, ulinzi wa ustaarabu, n.k.</li></ol><h2 id="_3-kanuni-za-msingi-za-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" tabindex="-1">3. Kanuni za Msingi za Maendeleo ya Pamoja ya Kabila Kumi na Elfu <a class="header-anchor" href="#_3-kanuni-za-msingi-za-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" aria-label="Permalink to &quot;3. Kanuni za Msingi za Maendeleo ya Pamoja ya Kabila Kumi na Elfu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui</th><th>Mahitaji Mahususi</th></tr></thead><tbody><tr><td>Kanuni ya Usawa wa Kabila</td><td>Makabila yote ni sawa katika hadhi ya kisheria na haki ya mageuzi</td><td>Kataa ubaguzi wa kabila, nafasi za umma zinafunguliwa kwa makabila yote</td></tr><tr><td>Kanuni ya Kuheshimu Utamaduni</td><td>Kuheshimu mila za kitamaduni na njia za maisha za kila kabila</td><td>Usilazimishe uingizwaji wa kitamaduni,ungaize urithi na ukuzaji wa utamaduni wa kabila</td></tr><tr><td>Kanuni ya Uingizwaji wa Faida</td><td>Shauri makabila kufanya kazi kwa kutumia faida zao</td><td>Tengeneza hifadhi ya data ya ujuzi wa kabila, kukuza miradi ya ushirikiano kati ya makabila</td></tr><tr><td>Kanuni ya Msaada wa Nyuma</td><td>Toa msaada wa ziada kwa makabila yenye kiwango cha chini cha mageuzi</td><td>Tengeneza fedha ya maendeleo ya kabila, toa elimu iliyoelekezwa na mgawanyo wa rasilimali</td></tr><tr><td>Kanuni ya Utautaji na Uongozi wa Pamoja</td><td>Mambo ya ndani ya kabila ni ya kitaalamu, mambo kati ya makabila ni ya uongozi wa pamoja</td><td>Kila kabila kina haki ya kutenga sheria za ndani, mambo ya umma yanafanywa na taasisi za jamhuri</td></tr><tr><td>Kanuni ya Kutatua Migogoro kwa Amani</td><td>Migogoro kati ya makabila inatuliwa kwa njia za amani</td><td>Kataa vita kati ya makabila, migogoro inapelekwa kwa mahakama ya Nanga kwa usuluhishi</td></tr></tbody></table><h2 id="_4-njia-ya-utekelezaji-wa-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" tabindex="-1">4. Njia ya Utekelezaji wa Maendeleo ya Pamoja ya Kabila Kumi na Elfu <a class="header-anchor" href="#_4-njia-ya-utekelezaji-wa-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" aria-label="Permalink to &quot;4. Njia ya Utekelezaji wa Maendeleo ya Pamoja ya Kabila Kumi na Elfu&quot;">​</a></h2><p>Maendeleo ya pamoja ya Kabila Kumi na Elfu sio sauti ya kupiga kelele, bali yanatekelezwa hatua kwa hatua kupitia njia maalum zifuatazo:</p><h3 id="_4-1-elimu-ya-jumla" tabindex="-1">4.1 Elimu ya Jumla <a class="header-anchor" href="#_4-1-elimu-ya-jumla" aria-label="Permalink to &quot;4.1 Elimu ya Jumla&quot;">​</a></h3><p>Tengeneza mfumo wa elimu ya usawa kati ya makabila, ambapo vijana wa makabila yote wanaweza kupokea elimu ya msingi ya mageuzi bila malipo. Maudhui ya elimu yanajumuisha njia za msingi za Mifumo Mia Tatu ya Uozi, maadili ya kupinga uwindaji, Katiba ya Ustaarabu wa Usawa, maarifa ya jumla ya ulimwengu, n.k. Wakati huo huo, heshima mila za elimu ya kitamaduni za kila kabila, na ruhusu kufanya elimu yenye sifa za kabila nje ya elimu ya jumla.</p><h3 id="_4-2-kushirikiwa-kwa-rasilimali" tabindex="-1">4.2 Kushirikiwa kwa Rasilimali <a class="header-anchor" href="#_4-2-kushirikiwa-kwa-rasilimali" aria-label="Permalink to &quot;4.2 Kushirikiwa kwa Rasilimali&quot;">​</a></h3><p>Kupitia mfumo wa mkataba unaohusishwa na uzalishaji, gawanya rasilimali za uozi za ulimwengu kwa umoja kulingana na idadi ya watu wa kabila, mahitaji ya mageuzi, na kiwango cha mchango. Kwa makabila yenye uhaba wa rasilimali, fanya mgawanyo wa rasilimali wa njia kupitia mtandao wa vitu vya nanga. Kataa kabila lolote kutumia milki ya rasilimali za umma za uozi.</p><h3 id="_4-3-utafiti-wa-teknolojia-ya-pamoja" tabindex="-1">4.3 Utafiti wa Teknolojia ya Pamoja <a class="header-anchor" href="#_4-3-utafiti-wa-teknolojia-ya-pamoja" aria-label="Permalink to &quot;4.3 Utafiti wa Teknolojia ya Pamoja&quot;">​</a></h3><p>Shauri utafiti wa ushirikiano wa teknolojia kati ya makabila, haswa miradi ya utafiti inayounganisha uwezo wa asili wa makabila tofauti na uhandisi wa sheria. Ustaarabu wa usawa unaanzisha &quot;Fedha ya Utafiti wa Pamoja wa Kabila Kumi na Elfu&quot;, inayofadhili timu za utafiti kati ya makabila. Matokeo ya utafiti yanafunguliwa bila malipo kwa makabila yote.</p><h3 id="_4-4-mzunguko-wa-viumbe-wenye-vipaji" tabindex="-1">4.4 Mzunguko wa Viumbe Wenye Vipaji <a class="header-anchor" href="#_4-4-mzunguko-wa-viumbe-wenye-vipaji" aria-label="Permalink to &quot;4.4 Mzunguko wa Viumbe Wenye Vipaji&quot;">​</a></h3><p>Vunja vikwazo vya viumbe wenye vipaji kati ya makabila, na ruhusu waozaji kusafiri na kubadilishana kwa uhuru kati ya maeneo ya makazi ya makabila tofauti. Tengeneza mfumo wa walimu kati ya makabila, ambapo waozaji wa juu wanaweza kuongoza waozaji wa awali wa makabila mengine.</p><h3 id="_4-5-ushiriki-wa-jamhuri" tabindex="-1">4.5 Ushiriki wa Jamhuri <a class="header-anchor" href="#_4-5-ushiriki-wa-jamhuri" aria-label="Permalink to &quot;4.5 Ushiriki wa Jamhuri&quot;">​</a></h3><p>Bunge la Jamhuri ya Kabila Kumi na Elfu linagawanya viti kwa umoja kulingana na idadi ya watu wa kabila na kiwango cha mchango, kuhakikisha kuwa hata makabila madogo yana njia ya sauti. Maamuzi ya bunge yanatumia mchanganyiko wa makubaliano kupitia mazungumzo na kura ya wengi, na mambo yanayohusu maslahi ya msingi ya kabila yanahitaji ridhaa ya kabila inayohusika.</p><h2 id="_5-sera-kwa-makabila-maalum" tabindex="-1">5. Sera kwa Makabila Maalum <a class="header-anchor" href="#_5-sera-kwa-makabila-maalum" aria-label="Permalink to &quot;5. Sera kwa Makabila Maalum&quot;">​</a></h2><p>Kwa makabila katika hali maalum, ustaarabu wa usawa unachukua sera tofauti:</p><ul><li><strong>Makabila Yanayotishiwa Kutoweka</strong>: Tengeneza mpango wa uhifadhi wa kabila, toa msaada wa dharura wa rasilimali na uhifadhi wa makazi, na wasaidie kurejesha idadi ya watu</li><li><strong>Makabila ya Uhai wa Kushangaza</strong>: Tathmini na weka makazi kulingana na mtiririko wa utunzaji wa kiwango cha aina tatu za uhai wa kushangaza, kuhakikisha kuwa haki yao ya mageuzi inalindwa</li><li><strong>Makabila ya Mseto wa Njia</strong>: Tambuta utambulisho wao wa kabila wa pili, na hakikisha haki zao sawa katika tamaduni zote mbili za kabila</li><li><strong>Makabila ya Awali ya Uwindaji</strong>: Kwa makabila ambayo kwa kihistoria yamefuata uwindaji, baada ya kukamilisha mabadiliko ya maadili na mabadiliko ya mfumo, patia hadhi sawa kabisa, na usifanye ubaguzi wa kurudia nyuma ya kihistoria</li></ul><h2 id="_6-vigezo-vya-kupima-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" tabindex="-1">6. Vigezo vya Kupima Maendeleo ya Pamoja ya Kabila Kumi na Elfu <a class="header-anchor" href="#_6-vigezo-vya-kupima-maendeleo-ya-pamoja-ya-kabila-kumi-na-elfu" aria-label="Permalink to &quot;6. Vigezo vya Kupima Maendeleo ya Pamoja ya Kabila Kumi na Elfu&quot;">​</a></h2><p>Ustaarabu wa usawa umeunda &quot;Fahirisi ya Maendeleo ya Pamoja ya Kabila Kumi na Elfu&quot;, inayopima maendeleo ya maendeleo ya pamoja ya Kabila Kumi na Elfu kutoka vipengele vifuatavyo:</p><table tabindex="0"><thead><tr><th>Kipengele</th><th>Kigezo</th><th>Malengo</th></tr></thead><tbody><tr><td>Kiwango cha Ufunuo wa Mageuzi</td><td>Ulinganisho wa makabila yaliyounganishwa na mfumo wa uozi</td><td>100%</td></tr><tr><td>Kiwango cha Usawa wa Kiwango</td><td>Kiwango cha tofauti ya kiwango cha wastani cha kila kabila</td><td>Kupungua kwa kila wakati</td></tr><tr><td>Uzito wa Ushirikiano</td><td>Idadi na kina ya miradi ya ushirikiano kati ya makabila</td><td>Kuongezeka kwa kila wakati</td></tr><tr><td>Uhai wa Utamaduni</td><td>Shughuli za urithi na ubunifu wa utamaduni wa kabila</td><td>Kudumisha utofauti</td></tr><tr><td>Kiwango cha Migogoro</td><td>Masafa ya kutokea kwa migogoro kati ya makabila</td><td>Kupungua kwa kila wakati</td></tr></tbody></table><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Maendeleo ya pamoja ya Kabila Kumi na Elfu ni moja ya malengo ya mwisho ya Ustaarabu wa Usawa wa Nanga na pia ni haki ya lazima ya kupanda mwelekeo kwa jumla ya ulimwengu. Chini ya mfumo wa ustaarabu wa usawa, kila kabila kinaweza kupata njia yake ya mageuzi, na utofauti wa kila kabila unaweza kuheshimiwa na kuonyeshwa. Maendeleo ya pamoja ya Kabila Kumi na Elfu hayamaanishi kuondoa tofauti, bali kufikia umoja katika tofauti na kutimiza usawa katika utofauti.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Tangazo la Ustaarabu wa Usawa wa Nanga)</li><li>50-万族谱系总览 (Muhtasari wa Nasaba ya Kabila Kumi na Elfu)</li><li>77-万族共和成立 (Kuanzishwa kwa Jamhuri ya Kabila Kumi na Elfu)</li></ul>',32)])])}const s=i(l,[["render",e]]);export{d as __pageData,s as default};
